            for r in conn.execute(f"SELECT * FROM users WHERE user_id IN ({uq})", user_ids)
        ]
        carts = [
            Cart.from_dict(_row_to_cart(r))
            for r in conn.execute(f"SELECT * FROM carts WHERE customer_id IN ({uq})", user_ids)
        ]
        cart_items = [
