            for r in conn.execute(f"SELECT * FROM cart_items WHERE customer_id IN ({uq})", user_ids)
        ]
        promotions = [
            Promotion.from_dict(_row_to_promotion(r))
            for r in conn.execute("SELECT * FROM promotions")
        ]
    finally:
        conn.close()
    return cls(
        products=products,
        customers=customers,
        carts=carts,
        cart_items=cart_items,
